export function parseHttpPipeError(res: any, logger: LoggerService): { message?: string } {
  if (!res.status) {
    return res;
  }
  try {
    return res.json();
  } catch (e) {
    logger.warn('Failed to parse response body', e);
  }
  return {};
}

